import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote", () => {
    it("should return processing fee only for a single sword (base premium + fee)", () => {
      const customer = { yearsWithMHPCO: 0 };
      const items = [{ type: "sword" }];
      // sword base: 100G, first-insurance +10% = 110G, processing fee +5G = 115G
      expect(quote(customer, items, 1)).toBe(115);
    });
    it("should compute base premium for amulet", () => {
      const customer = { yearsWithMHPCO: 0 };
      const items = [{ type: "amulet" }];
      // amulet base: 60G, first-insurance +10% = 66G, processing fee +5G = 71G
      expect(quote(customer, items, 1)).toBe(71);
    });
    it.todo("should compute base premium for staff");
    it.todo("should compute base premium for potion");
    it.todo("should compute base premium for a single component (rune)");
    it.todo("should apply bundle discount for 3 identical components");
    it.todo("should apply cursed surcharge of 50%");
    it.todo("should apply high enchantment surcharge of 30% for enchantment >= 5");
    it.todo("should apply loyalty discount of 20% for customers with >= 2 years");
    it.todo("should apply first-insurance surcharge of 10%");
    it.todo("should apply repeat-contract discount of 15% after first contract");
  });

  describe("claim", () => {
    it.todo("should deduct 100G deductible from total damage");
    it.todo("should reimburse 50% for items with enchantment >= 8");
    it.todo("should fully reimburse damage to dragon material items");
  });
});

